const lessons=[{"sentences":[{"speaker":"A","text":"Hello Mark, we really need to finish planning our geography field trip report this afternoon.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.726666666666667},{"speaker":"B","text":"Hi Sarah, I brought all my field notes and measurements from our visit to the river valley last week.","position":2,"audioStartSeconds":5.926666666666667,"audioEndSeconds":11.986833333333333},{"speaker":"A","text":"That is wonderful because our professor said we must clearly separate pure observation from personal opinion.","position":3,"audioStartSeconds":12.186833333333333,"audioEndSeconds":18.669541666666667},{"speaker":"B","text":"I remember that advice because mixing them up lowers our final grade significantly.","position":4,"audioStartSeconds":18.869541666666667,"audioEndSeconds":23.9605},{"speaker":"A","text":"Let us review our notes about the water speed near the old stone bridge first.","position":5,"audioStartSeconds":24.1605,"audioEndSeconds":29.083166666666667},{"speaker":"B","text":"I wrote down that the current felt very lazy and slow to me on Tuesday morning.","position":6,"audioStartSeconds":29.283166666666666,"audioEndSeconds":34.3605},{"speaker":"A","text":"Wait a minute, although the word lazy sounds descriptive, it actually expresses your personal feeling.","position":7,"audioStartSeconds":34.5605,"audioEndSeconds":41.00383333333333},{"speaker":"B","text":"You are completely right since another group measured an exact speed of zero point five metres per second.","position":8,"audioStartSeconds":41.203833333333336,"audioEndSeconds":47.440958333333334},{"speaker":"A","text":"Therefore, the numerical measurement is the proper scientific observation we should include in our text.","position":9,"audioStartSeconds":47.64095833333333,"audioEndSeconds":54.148666666666664},{"speaker":"B","text":"And my feeling about the river looking lazy belongs in our final reflection section instead.","position":10,"audioStartSeconds":54.34866666666667,"audioEndSeconds":60.01875},{"speaker":"A","text":"What about the strange brown foam we noticed floating near the northern bank?","position":11,"audioStartSeconds":60.21875,"audioEndSeconds":64.99966666666667},{"speaker":"B","text":"My first thought was that a nearby factory caused terrible pollution in the water.","position":12,"audioStartSeconds":65.19966666666667,"audioEndSeconds":70.277},{"speaker":"A","text":"While that might be true, we did not test the water chemistry to prove any industrial damage.","position":13,"audioStartSeconds":70.477,"audioEndSeconds":76.36620833333333},{"speaker":"B","text":"So stating that the factory polluted the river would be an unsupported opinion rather than a fact.","position":14,"audioStartSeconds":76.56620833333334,"audioEndSeconds":82.30075},{"speaker":"A","text":"We should simply write that brown foam was present on the surface without assuming its origin.","position":15,"audioStartSeconds":82.50075,"audioEndSeconds":88.13216666666666},{"speaker":"B","text":"That makes complete sense and keeps our scientific methodology objective and valid.","position":16,"audioStartSeconds":88.33216666666667,"audioEndSeconds":93.589875},{"speaker":"A","text":"Shall we draft the observation paragraphs now and leave the opinions for our conclusion?","position":17,"audioStartSeconds":93.789875,"audioEndSeconds":99.25620833333333},{"speaker":"B","text":"Yes, let us write them down that way right now.","position":18,"audioStartSeconds":99.45620833333334,"audioEndSeconds":103.1255}],"questions":[{"prompt":"Why do the students need to separate observation from opinion in their report?","options":["Their professor warned that mixing them lowers their grade.","The university library requires a specific formatting style.","Their classmates complained about confusing descriptions."],"answer":"A","evidenceSentence":4,"evidence":"I remember that advice because mixing them up lowers our final grade significantly.","explanation":"Giảng viên đã cảnh báo rằng việc trộn lẫn quan sát và ý kiến sẽ làm giảm điểm số đáng kể."},{"prompt":"What did Mark initially write about the water speed near the bridge?","options":["He recorded an exact speed of zero point five metres.","He felt that the current was very lazy and slow.","He noticed that the river flow stopped completely."],"answer":"B","evidenceSentence":6,"evidence":"I wrote down that the current felt very lazy and slow to me on Tuesday morning.","explanation":"Mark ban đầu ghi chép rằng dòng nước cho cảm giác rất lười biếng và chậm chạp."},{"prompt":"How do they classify Mark's original description of the water speed?","options":["As a certified scientific measurement.","As an objective geographical fact.","As a personal feeling or opinion."],"answer":"C","evidenceSentence":7,"evidence":"Wait a minute, although the word lazy sounds descriptive, it actually expresses your personal feeling.","explanation":"Họ phân loại từ 'lười biếng' là một cảm xúc hoặc ý kiến cá nhân chứ không phải dữ liệu khách quan."},{"prompt":"What did Mark initially assume caused the brown foam near the northern bank?","options":["Heavy rainfall washing soil into the river.","A nearby factory causing terrible pollution.","Natural decay of plants along the bank."],"answer":"B","evidenceSentence":12,"evidence":"My first thought was that a nearby factory caused terrible pollution in the water.","explanation":"Ban đầu Mark nghĩ rằng một nhà máy gần đó đã gây ra ô nhiễm tồi tệ."},{"prompt":"Why do they decide not to mention the factory in the observation section?","options":["They did not test the water chemistry to prove industrial damage.","They forgot to take photographs of the factory.","The factory was located too far away from the bridge."],"answer":"A","evidenceSentence":13,"evidence":"While that might be true, we did not test the water chemistry to prove any industrial damage.","explanation":"Họ chưa kiểm tra hóa học nước để chứng minh thiệt hại công nghiệp nên không thể đưa vào phần quan sát."},{"prompt":"What do the speakers finally agree to do next?","options":["Submit the report immediately without review.","Draft the observation paragraphs now and leave opinions for the conclusion.","Ask their professor for extra help with the measurements."],"answer":"B","evidenceSentence":17,"evidence":"Shall we draft the observation paragraphs now and leave the opinions for our conclusion?","explanation":"Họ đồng ý viết các đoạn quan sát ngay bây giờ và để lại các ý kiến cho phần kết luận."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
